Path('dedup-regression.test.ts').write_text('''import { test, expect, afterAll } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import { DedupStrategy } from "./src/core/context-pruning/dedup.ts";

const root = mkdtempSync(join(import.meta.dir, "check-output-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "匹配: example 😀\\n".repeat(500);
const args = { query: "example" };
const run = (tracker: ContextPruningTracker, call: string) => tracker.process(
  call, "code_search", args, output, recoverablePrune(root, "session", call, output),
);

test("retained output and byte statistics survive history reload", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(second.modified).toBe(true);
  expect(third.output).toContain("callId: first");
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory()[1].originalOutput).toBe(output);
  expect(tracker.getHistory()[1].prunedOutput).toBe(second.output);
  expect(tracker.getHistory()[2].prunedOutput).toBe(third.output);
  expect(tracker.getStats()).toEqual({
    totalCalls: 3, prunedCalls: 2,
    totalBytesSaved: 2 * Buffer.byteLength(output) - Buffer.byteLength(second.output) - Buffer.byteLength(third.output),
    estimatedContextBytes: Buffer.byteLength(output) + Buffer.byteLength(second.output) + Buffer.byteLength(third.output),
  });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "fourth").output).toContain("callId: first");
});

test("evicted full output requires a new baseline, including after reload", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "evicted");
  run(tracker, "short-1");
  run(tracker, "short-2");
  const loaded = new ContextPruningTracker(root, 2);
  loaded.loadHistory(tracker.getHistory());
  for (const current of [tracker, loaded]) {
    expect(run(current, "baseline").modified).toBe(false);
    expect(run(current, "repeat").output).toContain("callId: baseline");
  }
});

test("rejected recovery becomes the most recent full baseline", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "older");
  const rejected = tracker.process("rejected", "code_search", args, output,
    recoverablePrune(root, "", "rejected", output));
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({ totalCalls: 2, prunedCalls: 0, totalBytesSaved: 0, estimatedContextBytes: 2 * Buffer.byteLength(output) });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(tracker.getHistory());
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "after-rejected").output).toContain("callId: rejected");
});

test("recovery rejects enlargement and storage failure without savings", () => {
  const invalidRoot = join(root, "file");
  writeFileSync(invalidRoot, "not a directory");
  for (const [cwd, text] of [[root, "tiny"], [invalidRoot, output]]) {
    const tracker = new ContextPruningTracker(cwd);
    const process = (id: string) => tracker.process(id, "code_search", args, text, recoverablePrune(cwd, "session", id, text));
    process("one");
    expect(process("two")).toEqual({ output: text, modified: false, bytesSaved: 0 });
    expect(tracker.getHistory()[1].prunedOutput).toBeNull();
    expect(tracker.getStats().prunedCalls).toBe(0);
    expect(tracker.getStats().totalBytesSaved).toBe(0);
  }
});

test("different arguments and outputs stay distinct and matching full history is searched", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.process("a", "code_search", args, output);
  expect(tracker.process("b", "code_search", { query: "other" }, output).modified).toBe(false);
  expect(tracker.process("c", "code_search", args, output + "changed").modified).toBe(false);
  expect(tracker.process("d", "code_search", args, output).output).toContain("callId: a");
  expect(tracker.process("e", "code_search", args, output).output).toContain("callId: a");
});

test("shortened emitted text is never eligible as a full target", () => {
  const strategy = new DedupStrategy(root);
  const result = strategy.apply("code_search", args, "shortened", [{
    callId: "short", toolName: "code_search", args, originalOutput: output,
    prunedOutput: "shortened", timestamp: 1,
  }]);
  expect(result).toEqual({ output: "shortened", modified: false, bytesSaved: 0 });
});

test("side-effecting tools remain unchanged", () => {
  const tracker = new ContextPruningTracker(root);
  for (const tool of ["Bash", "Write", "Edit", "mcp__aide__memory_add", "task_update"]) {
    tracker.process(`${tool}-1`, tool, args, output);
    expect(tracker.process(`${tool}-2`, tool, args, output)).toEqual({ output, modified: false, bytesSaved: 0 });
  }
});
